contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(
        address baseToken,
        address nft,
        uint128 vBase,
        uint128 vNft,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useOracle,
        bool payRoyalties
    ) public payable {
        require(baseToken == address(0), "only ETH pool");
        c.initialize(
            baseToken,
            nft,
            vBase,
            vNft,
            changeFee,
            feeRate,
            merkleRoot,
            useOracle,
            payRoyalties
        );

        uint128 beforeBase = c.virtualBaseTokenReserves();
        uint128 beforeNft = c.virtualNftReserves();
        uint256 p = c.price();

        assert(p == (uint256(beforeBase) * 10**18) / uint256(beforeNft));
    }
}

contract InvMutTest {
